source("helper.R")
d <- zujson::json_parse(paste(readLines("data/sig.json", warn = FALSE), collapse = "\n"), simplify = "none"); t <- d$tokens
k <- function(label, x) { r <- try_(label, if (is.character(x) && grepl("keys", x) && FALSE) as_jwk_set(x) else as_jwk(x)); if (inherits(r, "jwk")) cat("     kty", r$kty, "bits", r$bits %||% NA, "supported", r$supported, "priv", if (r$kty != "oct") zujose:::has_private(r) else NA, "kid", r$kid %||% "-", "tp", tryCatch(jwk_thumbprint(r), error = function(e) class(e)[1]), "\n"); invisible(r) }
J <- function(x) zujson::json_parse(x, simplify = "none"); W <- function(x) zujson::json_write(x)
rsa <- J(d$rsa_jwk_pub); rsap <- J(d$rsa_jwk_priv)
k("rsa pub", W(rsa))
n <- unb64(rsa$n); m <- rsa; m$n <- b64(c(as.raw(0), n)); r <- k("rsa n leading zero", W(m)); if (inherits(r, "jwk")) try_("  verify RS256 w/ it", jws_verify(t$RS256, r, "RS256"))
m <- rsa; m$e <- b64(c(as.raw(0), unb64(rsa$e))); r <- k("rsa e leading zero", W(m)); if (inherits(r, "jwk")) try_("  verify RS256 w/ it", jws_verify(t$RS256, r, "RS256"))
m <- rsa; m$e <- "AQAB="; k("rsa e padded", W(m)); m$e <- "AQAC"; k("rsa e even(65538)", W(m)); m$e <- "AQ"; r <- k("rsa e=1", W(m))
if (inherits(r, "jwk")) { # forge with e=1: sig = EMSA padded digest
  try_("  e=1 forgery attempt runs", jws_verify(t$RS256, r, "RS256")) }
m <- rsa; m$e <- ""; k("rsa e empty", W(m)); m <- rsa; m$n <- ""; k("rsa n empty", W(m)); m <- rsa; m$n <- 5; k("rsa n number", W(m)); m <- rsa; m$n <- NULL; k("rsa no n", W(m))
m <- rsa; m$n <- b64(n[1:128]); k("rsa 1024", W(m)); m <- rsa; m$n <- b64(c(n, n, n, n, n)); k("rsa 10240 bits", W(m)); m$n <- b64(rep(n, 9)); k("rsa 18432 bits", W(m))
m <- rsap; m$oth <- list(list(r = "AQAB", d = "AQAB", t = "AQAB")); r <- k("rsa priv with oth (multi-prime)", W(m))
m <- rsap; m$d <- NULL; k("rsa priv no d", W(m)); m <- rsap; m$dp <- NULL; m$dq <- NULL; m$qi <- NULL; k("rsa priv d,p,q only", W(m)); m <- rsap; m$p <- NULL; m$q <- NULL; m$dp <- NULL; m$dq <- NULL; m$qi <- NULL; k("rsa priv d only", W(m))
m <- rsap; m$d <- b64(rev(unb64(rsap$d))); r <- k("rsa priv wrong d", W(m)); m <- rsap; tmp <- m$p; m$p <- m$q; m$q <- tmp; k("rsa priv p/q swapped", W(m))
m <- rsap; m$dp <- b64(as.raw(3)); k("rsa priv wrong dp", W(m)); m <- rsap; m$p <- b64(as.raw(c(1, 0, 1))); k("rsa priv wrong p", W(m))
m <- rsap; m$d <- 5; k("rsa priv d number", W(m)); m <- rsap; m$p <- 5; k("rsa priv p number", W(m)); m <- rsap; m$qi <- NULL; m$qi <- list("a"); k("rsa priv qi array", W(m))
cat("--- EC\n")
ec <- J(d[["ec_P-256_jwk_priv"]]); ecpub <- ec; ecpub$d <- NULL
k("ec pub", W(ecpub))
x <- unb64(ec$x); y <- unb64(ec$y)
m <- ecpub; m$x <- b64(c(as.raw(0), x)); m$y <- b64(c(as.raw(0), y)); r <- k("ec coords padded 33", W(m)); if (inherits(r, "jwk")) try_("  verify ES256", jws_verify(t$ES256, r, "ES256"))
m <- ecpub; m$y <- b64(rev(y)); k("ec off-curve", W(m)); m <- ecpub; m$y <- NULL; k("ec no y", W(m)); m <- ecpub; m$crv <- "P-384"; k("ec wrong crv", W(m)); m$crv <- "secp256k1"; k("ec secp256k1", W(m)); m$crv <- "p-256"; k("ec crv lower", W(m)); m$crv <- 256; k("ec crv number", W(m)); m$crv <- NULL; k("ec no crv", W(m))
m <- ecpub; m$x <- b64(raw(32)); m$y <- b64(raw(32)); k("ec zero point", W(m))
m <- ec; m$d <- b64(rev(unb64(ec$d))); r <- k("ec d not matching public", W(m))
m <- ec; m$d <- b64(raw(32)); k("ec d zero", W(m)); m$d <- b64(as.raw(rep(255, 32))); k("ec d >= n", W(m)); m$d <- ""; r <- k("ec d empty", W(m)); m$d <- b64(c(as.raw(0), unb64(ec$d))); k("ec d padded", W(m)); m$d <- 5; k("ec d number", W(m))
m <- ec; m$x <- NULL; m$y <- NULL; k("ec d only", W(m))
m <- ecpub; m$kty <- "OKP"; k("OKP with P-256", W(m)); m <- ecpub; m$kty <- "ec"; r <- k("kty lowercase", W(m))
cat("--- OKP\n")
xj <- J(d$x25519_jwk_priv); k("x25519 priv", W(xj)); m <- xj; m$d <- b64(rev(unb64(xj$d))); k("x25519 d mismatch", W(m)); m <- xj; m$x <- b64(raw(32)); k("x25519 x zero", W(m)); m <- xj; m$x <- b64(unb64(xj$x)[1:31]); k("x25519 x 31", W(m))
m <- xj; m$crv <- "X448"; k("X448", W(m)); k("ed25519", d$ed25519_jwk)
cat("--- oct / common\n")
k("oct", '{"kty":"oct","k":"AAAA"}'); k("oct empty k", '{"kty":"oct","k":""}'); k("oct no k", '{"kty":"oct"}'); k("oct k padded", '{"kty":"oct","k":"AAAA=="}'); k("oct k std alphabet", '{"kty":"oct","k":"++++"}'); k("oct k noncanon", '{"kty":"oct","k":"AAB"}')
k("oct k number", '{"kty":"oct","k":5}'); k("oct k array", '{"kty":"oct","k":["AAAA"]}'); k("kty missing", '{"k":"AAAA"}'); k("kty number", '{"kty":1}'); k("kty unknown", '{"kty":"XYZ","k":"AAAA"}'); k("kty null", '{"kty":null}')
k("dup member", '{"kty":"oct","k":"AAAA","k":"AAAB"}'); k("kid number", '{"kty":"oct","k":"AAAA","kid":5}'); k("kid null", '{"kty":"oct","k":"AAAA","kid":null}'); k("alg number", '{"kty":"oct","k":"AAAA","alg":5}'); k("alg unknown", '{"kty":"oct","k":"AAAA","alg":"zzz"}')
k("use unknown", '{"kty":"oct","k":"AAAA","use":"zzz"}'); k("use number", '{"kty":"oct","k":"AAAA","use":1}'); k("key_ops dup", '{"kty":"oct","k":"AAAA","key_ops":["sign","sign"]}'); k("key_ops null", '{"kty":"oct","k":"AAAA","key_ops":null}')
k("key_ops [null]", '{"kty":"oct","k":"AAAA","key_ops":[null]}'); k("key_ops nested", '{"kty":"oct","k":"AAAA","key_ops":[["sign"]]}')
k("json array", '[{"kty":"oct","k":"AAAA"}]'); k("json ws", ' \n {"kty":"oct","k":"AAAA"} '); k("json trailing", '{"kty":"oct","k":"AAAA"} x'); k("not json", 'hello'); k("empty", ''); k("NA", NA_character_); k("vec2", c("a", "b")); k("list", list(kty = "oct", k = "AAAA")); k("list unnamed", list("oct")); k("NULL", NULL); k("number", 5)
k("list k raw", list(kty = "oct", k = as.raw(1:4)))
k("oct with x5c etc", '{"kty":"oct","k":"AAAA","x5c":["abc"],"x5u":"http://x","ext":true,"custom":{"a":1}}')
cat("--- PEM\n")
pem <- d$rsa_pub_spki
k("pem leading ws", paste0("\n  ", pem)); k("pem trailing junk", paste0(pem, "junk")); k("pem two keys", paste0(pem, d$rsa1024_pub)); k("pem CRLF", gsub("\n", "\r\n", pem)); k("pem no newline at end", sub("\n$", "", pem))
k("pem truncated", substr(pem, 1, 200)); k("pem cert-like header", sub("PUBLIC KEY", "CERTIFICATE", gsub("PUBLIC KEY", "CERTIFICATE", pem))); k("pem body garbage", "-----BEGIN PUBLIC KEY-----\nAAAA\n-----END PUBLIC KEY-----\n")
k("pem text before", paste0("Subject: x\n", pem)); k("pem enc priv", d$rsa_enc_priv); k("pem vector lines", strsplit(pem, "\n")[[1]])
cat("--- sets\n")
s <- function(label, x) { r <- try_(label, as_jwk_set(x)); if (inherits(r, "jwk_set")) cat("     ", paste(format(r), collapse = " | "), "\n"); invisible(r) }
s("set ok", sprintf('{"keys":[%s,%s]}', d$rsa_jwk_pub, d[["ec_P-256_jwk_priv"]])); s("set empty", '{"keys":[]}'); s("set keys object", '{"keys":{}}'); s("set keys null", '{"keys":null}'); s("set no keys", '{}'); s("set array top", '[]')
s("set w/ bad + unknown + ed", sprintf('{"keys":[%s,{"kty":"XYZ"},{"kty":"oct"},5,null,"str",%s,{"kty":"RSA","n":"AQAB","e":"AQAB"}]}', d$rsa_jwk_pub, d$ed25519_jwk))
s("set dup kid", '{"keys":[{"kty":"oct","k":"AAAA","kid":"a"},{"kty":"oct","k":"AAAB","kid":"a"}]}'); s("set dup member in key", '{"keys":[{"kty":"oct","k":"AAAA","k":"AAAB"}]}'); s("set dup keys member", '{"keys":[],"keys":[{"kty":"oct","k":"AAAA"}]}')
s("set single jwk", '{"kty":"oct","k":"AAAA"}'); s("set from list", list(keys = list(list(kty = "oct", k = "AAAA")))); s("set extra members", '{"keys":[{"kty":"oct","k":"AAAA"}],"foo":1}')
s("set 1000 keys", sprintf('{"keys":[%s]}', paste(rep('{"kty":"oct","k":"AAAA"}', 1000), collapse = ",")))
# dup kid in set + token kid -> tries both
ks <- as_jwk_set(sprintf('{"keys":[{"kty":"oct","k":"%s","kid":"a"},{"kty":"oct","k":"%s","kid":"a"}]}', b64(as.raw(101:132)), b64(K32)))
r <- try_("dup-kid set verify", jws_verify(hs('{"alg":"HS256","kid":"a"}', "x", K32), ks, "HS256"))
# unsupported key in set matched by kid
ks2 <- as_jwk_set(sprintf('{"keys":[%s]}', d$ed25519_jwk)); try_("set w/ only Ed25519 for ES256", jws_verify(t$ES256, ks2, "ES256"))
# weak key in set skipped
ks3 <- jwk_set(jwk_oct(as.raw(1:16)), jwk_oct(K32)); try_("weak+strong set", jws_verify(hs('{"alg":"HS256"}', "x", K32), ks3, "HS256")); try_("weak+strong set, signed by weak", jws_verify(hs('{"alg":"HS256"}', "x", as.raw(1:16)), ks3, "HS256"))
ks4 <- jwk_set(as_jwk(d$rsa1024_pub), as_jwk(d$rsa_pub_spki)); try_("1024+2048 set", jws_verify(t$RS256, ks4, "RS256")); try_("1024+2048 set, signed by 1024", jws_verify(t$RS256_1024, ks4, "RS256"))
print(as_jwk(d$rsa_jwk_priv)); print(as_jwk('{"kty":"oct","k":"c2VjcmV0c2VjcmV0"}')); str(unclass(as_jwk('{"kty":"oct","k":"AAAA","d":"x","custom":1}'))[c("k","members")])
